    Hub hub(c1, c2, c3, c4, c5);
    Client c1(hub);
    Client c2(hub);
    Client c3(hub);
    Client c4(hub);
    Client c5(hub);

    // Start all clients (equivalent to sending "start")
    c1.start();
    c2.start();
    c3.start();
    c4.start();
    c5.start();
}

